  static float R(float a,float b){return Mathf.Lerp(a,b,(float)random.NextDouble());}
  static Vector3 V(float x,float y,float z){return new Vector3(x,y,z);}
  static Color C(string h){ColorUtility.TryParseHtmlString(h,out var c);return c;}
  static float Ground(float x,float z){return -.8f+.018f*z+.115f*x+1.3f*Mathf.Sin(z*.052f+x*.027f)+.0009f*x*x;}
  static Transform Group(string n){return new GameObject(n).transform;}
  static Material Mat(string n,string hex){var m=new Material(Shader.Find("Universal Render Pipeline/Lit")){name=n};m.SetColor("_BaseColor",C(hex));m.SetFloat("_Smoothness",0);m.SetFloat("_SpecularHighlights",0);m.SetFloat("_EnvironmentReflections",0);m.enableInstancing=true;AssetDatabase.CreateAsset(m,Root+"/Materials/"+n+".mat");return m;}
  static GameObject Shape(string n,Mesh mesh,Vector3 p,Vector3 s,Material mat,Transform parent){var g=new GameObject(n,typeof(MeshFilter),typeof(MeshRenderer));g.transform.SetParent(parent,false);g.transform.position=p;g.transform.localScale=s;g.GetComponent<MeshFilter>().sharedMesh=mesh;g.GetComponent<MeshRenderer>().sharedMaterial=mat;return g;}
  static GameObject Box(string n,Vector3 p,Vector3 s,Material mat,Transform parent){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=n;g.transform.SetParent(parent,false);g.transform.position=p;g.transform.localScale=s;g.GetComponent<Renderer>().sharedMaterial=mat;UnityEngine.Object.DestroyImmediate(g.GetComponent<Collider>());return g;}
  static void Tri(List<Vector3> v,List<int> t,Vector3 a,Vector3 b,Vector3 c,Vector3 normal){if(Vector3.Dot(Vector3.Cross(b-a,c-a),normal)<0){var tmp=b;b=c;c=tmp;}int k=v.Count;v.Add(a);v.Add(b);v.Add(c);t.Add(k);t.Add(k+1);t.Add(k+2);}
  static void Quad(List<Vector3> v,List<int> t,Vector3 a,Vector3 b,Vector3 c,Vector3 d,Vector3 n){Tri(v,t,a,b,c,n);Tri(v,t,a,c,d,n);}
  static Mesh SaveMesh(string n,List<Vector3> v,List<int> t){var m=new Mesh{name=n,indexFormat=IndexFormat.UInt32};m.SetVertices(v);m.SetTriangles(t,0);m.RecalculateNormals();m.RecalculateBounds();AssetDatabase.CreateAsset(m,Root+"/Meshes/"+n+".asset");return m;}
  static Mesh Radial(string n,int sides,bool pointed){var v=new List<Vector3>();var t=new List<int>();for(int i=0;i<sides;i++){float a=i*Mathf.PI*2/sides,b=(i+1)*Mathf.PI*2/sides;var p=V(Mathf.Cos(a),0,Mathf.Sin(a));var q=V(Mathf.Cos(b),0,Mathf.Sin(b));if(pointed){p.y=i%2==0?.09f:-.07f;q.y=(i+1)%2==0?.09f:-.07f;Tri(v,t,p,V(.04f,1,0),q,p+q);Tri(v,t,Vector3.zero,q,p,Vector3.down);}else {Quad(v,t,p,q,q*.72f+Vector3.up,p*.72f+Vector3.up,p+q);Tri(v,t,Vector3.up,p*.72f+Vector3.up,q*.72f+Vector3.up,Vector3.up);}}return SaveMesh(n,v,t);}
  static Mesh RockMesh(){var v=new List<Vector3>();var t=new List<int>();var lo=new Vector3[7];var hi=new Vector3[7];for(int i=0;i<7;i++){float a=i*Mathf.PI*2/7;lo[i]=V(Mathf.Cos(a)*R(.8f,1.1f),-.4f,Mathf.Sin(a)*R(.8f,1.1f));hi[i]=V(lo[i].x*R(.55f,.9f),R(.3f,.7f),lo[i].z*R(.55f,.9f));}for(int i=0;i<7;i++){int j=(i+1)%7;Quad(v,t,lo[i],lo[j],hi[j],hi[i],lo[i]+lo[j]);Tri(v,t,hi[i],hi[j],V(0,.62f,0),Vector3.up);Tri(v,t,Vector3.down*.4f,lo[j],lo[i],Vector3.down);}return SaveMesh("Angular_Weathered_Rock",v,t);}
  static void Tree(float x,float z,float h,Transform parent,bool bare=false){float y=Ground(x,z);var g=new GameObject(bare?"Foreground bare pine":"Layered alpine pine").transform;g.SetParent(parent,false);g.position=V(x,y,z);Shape("Tapered bark",trunk,V(x,y,z),V(h*.048f,h,h*.048f),bark,g);if(bare){for(int i=0;i<4;i++){var branch=Shape("Broken branch",trunk,V(x,y+h*(.3f+i*.16f),z),V(h*.018f,h*.17f,h*.018f),bark,g);branch.transform.rotation=Quaternion.Euler(0,i*100,55);}return;}for(int j=0;j<5;j++){float k=j/5f;var b=Shape("Irregular evergreen tier",cone,V(x,y+h*(.22f+k*.63f),z),V(h*(.245f-k*.20f),h*(.37f-k*.14f),h*(.235f-k*.19f)),foliage[(j+random.Next(3))%foliage.Length],g);b.transform.rotation=Quaternion.Euler(0,R(0,360),0);}}
  static void Terrain(Transform parent){var v=new List<Vector3>();var t=new List<int>();var colors=new List<Color>();for(int z=-35;z<200;z+=3)for(int x=-120;x<121;x+=3){var a=V(x,Ground(x,z),z);var b=V(x+3,Ground(x+3,z),z);var c=V(x+3,Ground(x+3,z+3),z+3);var d=V(x,Ground(x,z+3),z+3);Quad(v,t,a,b,c,d,Vector3.up);}var mesh=SaveMesh("Rolling_Valley",v,t);Shape("Sculpted valley",mesh,Vector3.zero,Vector3.one,grass[0],parent);}
  static void Grass(Transform parent){for(int batch=0;batch<6;batch++){var v=new List<Vector3>();var t=new List<int>();for(int i=0;i<9000;i++){float x=R(-65,65),z=R(-20,105);if(z>45&&random.NextDouble()<.5)continue;if(Mathf.Pow((x-10)/8,2)+Mathf.Pow((z-22)/7,2)<1)continue;float y=Ground(x,z)+.01f;float h=R(.10f,.44f),w=R(.035f,.11f),a=R(0,6.28f);var r=V(Mathf.Cos(a)*w,0,Mathf.Sin(a)*w);var p=V(x,y,z);Tri(v,t,p-r,p+r,p+V(R(-.12f,.12f),h,R(-.1f,.1f)),Vector3.up);Tri(v,t,p+r,p-r,p+V(R(-.12f,.12f),h,R(-.1f,.1f)),Vector3.down);}Shape("Meadow blade cluster "+batch,SaveMesh("Grass_"+batch,v,t),Vector3.zero,Vector3.one,grass[batch%grass.Length],parent);}}
  static Vector3 DomeP(float phi,float theta,float r){return V(Mathf.Sin(phi)*Mathf.Sin(theta)*r,Mathf.Cos(phi)*r*.71f,-Mathf.Sin(phi)*Mathf.Cos(theta)*r);}
  static void Dome(Transform parent){var center=V(10,Ground(10,22)-.18f,22);var g=Group("Ancient stone shelter");g.SetParent(parent,false);int count=0;for(int ring=0;ring<7;ring++){float p0=ring*Mathf.PI/14,p1=(ring+1)*Mathf.PI/14;int sides=ring<2?16:28;float step=Mathf.PI*2/sides;for(int s=0;s<sides;s++){float theta=(s+.5f+(ring%2)*.5f)*step;if(ring>=4&&Mathf.Abs(Mathf.DeltaAngle(theta*Mathf.Rad2Deg,0))<19)continue;float a=(s+(ring%2)*.5f)*step+.006f,b=a+step-.012f;var v=new List<Vector3>();var t=new List<int>();float rr=7.3f+R(-.025f,.025f);var q0=DomeP(p0+.003f,a,rr);var q1=DomeP(p0+.003f,b,rr);var q2=DomeP(p1-.003f,b,rr);var q3=DomeP(p1-.003f,a,rr);Quad(v,t,q0,q1,q2,q3,q0+q1+q2+q3);Shape("Weathered masonry course "+ring+" block "+s,SaveMesh("Dome_Block_"+(count++),v,t),center,Vector3.one,stone[random.Next(stone.Length)],g);}}
   float front=center.z-6.9f;var door=Box("Recessed charcoal sealed door",V(10,center.y+1.75f,front+.13f),V(3.25f,3.5f,.28f),dark,g);
   Box("Door central seam",V(10,center.y+1.7f,front-.026f),V(.045f,3.3f,.025f),metal,g);
