   Box("Heavy weathered lintel",V(10,center.y+3.92f,front-.22f),V(3.65f,.58f,1.0f),stone[1],g);Box("Ochre inner lintel",V(10,center.y+3.35f,front-.34f),V(2.65f,.14f,.12f),metal,g);
   for(int i=0;i<36;i++){float a=R(-1.6f,1.6f);float x=10+Mathf.Sin(a)*R(6.8f,8.7f),z=22-Mathf.Cos(a)*R(6.3f,8.2f);Shape("Fallen dome fragment",rock,V(x,Ground(x,z)+.25f,z),V(R(.25f,.85f),R(.25f,.8f),R(.3f,.9f)),stone[random.Next(stone.Length)],parent).transform.rotation=Quaternion.Euler(R(-15,20),R(0,360),R(-20,20));}
  }
  static void Ruins(Transform parent){for(int i=0;i<22;i++){float x=-105+i*10+R(-3,3),z=R(122,185),h=R(25,57);var g=Group("Distant broken tower "+i);g.SetParent(parent,false);float y=Ground(x,z);Box("Concrete spine",V(x,y+h*.5f,z),V(R(4,7),h,R(4,8)),farStone,g);Box("Broken crown",V(x+1,y+h+1.8f,z),V(2,3.6f,4),farStone,g);if(i%3==0){Box("Secondary spine",V(x+8,y+h*.4f,z),V(2.2f,h*.8f,4),farStone,g);for(int b=1;b<4;b++)Box("Open cross bridge",V(x+4,y+h*b/4,z),V(8,1,3),farStone,g);}}
