  public static void Generate(){if(File.Exists(ScenePath))throw new InvalidOperationException("Scene exists. Open it instead of overwriting edits.");random=new System.Random(47612);Directory.CreateDirectory(Root+"/Materials");Directory.CreateDirectory(Root+"/Meshes");Directory.CreateDirectory(Root+"/Preview");AssetDatabase.Refresh();EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);
