  static void Polish()
  {
   var scene=EditorSceneManager.OpenScene(ScenePath);
   var dome=GameObject.Find("Ancient stone shelter").transform;
   var center=V(10,Ground(10,22)-.18f,22);dome.localScale=Vector3.one*1.55f;dome.position=center-center*1.55f+V(7,Ground(17,22)-Ground(10,22),0);
   var forest=GameObject.Find("03 - Evergreen forest depth layers").transform;
   for(int i=forest.childCount-1;i>=0;i--){var tree=forest.GetChild(i);var p=tree.position;if((p.z>35&&(i%3==0||Mathf.Abs(p.x-17)<13&&p.z<75))){UnityEngine.Object.DestroyImmediate(tree.gameObject);continue;}var bark=tree.Find("Tapered bark");if(bark&&tree.name!="Foreground bare pine"){var scale=bark.localScale;scale.y*=.8f;bark.localScale=scale;}}
   var city=GameObject.Find("04 - Lost city and broken viaduct").transform;
   for(int i=city.childCount-1;i>=0;i--){var child=city.GetChild(i);if(child.name.StartsWith("Distant broken tower ")&&int.TryParse(child.name.Substring("Distant broken tower ".Length),out int index)&&index%2!=0)UnityEngine.Object.DestroyImmediate(child.gameObject);}
   for(int i=0;i<6;i++){var mesh=AssetDatabase.LoadAssetAtPath<Mesh>(Root+"/Meshes/Grass_"+i+".asset");var normals=new Vector3[mesh.vertexCount];for(int k=0;k<normals.Length;k++)normals[k]=Vector3.up;mesh.normals=normals;EditorUtility.SetDirty(mesh);}
